import{_ as o,H as a,f as n,i as s}from"./chunks/framework.CSxcEb-0.js";const p=JSON.parse('{"title":"Google Calendar sync","description":"","frontmatter":{},"headers":[],"relativePath":"guide/google-calendar.md","filePath":"guide/google-calendar.md"}'),r={name:"guide/google-calendar.md"};function t(l,e,i,c,d,g){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="google-calendar-sync" tabindex="-1">Google Calendar sync <a class="header-anchor" href="#google-calendar-sync" aria-label="Permalink to &quot;Google Calendar sync&quot;">​</a></h1><p>Connect Google Calendar so meetings and events block auto-scheduling, and optionally push TemPad changes back to Google.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ol><li><strong>Sign in with Google</strong> (Firebase) — not local-only mode</li><li>Enable the <a href="https://console.cloud.google.com/apis/library/calendar-json.googleapis.com" target="_blank" rel="noreferrer">Google Calendar API</a> on your Firebase/Google Cloud project</li><li>Add your site domain under Firebase <strong>Authentication → Authorized domains</strong> (e.g. <code>localhost</code>, <code>jaredescott.github.io</code>)</li></ol><h2 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h2><ol><li>Open <strong>Settings → Google Calendar sync</strong></li><li>Click <strong>Connect calendars</strong> and approve calendar access</li><li>Enable each calendar you want as busy blocks (work, personal, shared, etc.)</li><li>Use <strong>Sync now</strong> for an immediate pull; otherwise TemPad syncs periodically while the tab is open and when you return to the tab</li></ol><p>Synced events cover the next 8 weeks (plus range when you navigate outside that horizon). Google event colors appear on the week view.</p><h2 id="what-syncs-both-ways" tabindex="-1">What syncs both ways <a class="header-anchor" href="#what-syncs-both-ways" aria-label="Permalink to &quot;What syncs both ways&quot;">​</a></h2><ul><li><strong>Import:</strong> Google events → TemPad busy blocks</li><li><strong>Edits:</strong> Changes to imported events in TemPad push back when permissions allow</li><li><strong>Recurring deletes:</strong> Deleting one occurrence, occurrences from a date forward, or an entire series from TemPad calls the Google Calendar API when the calendar is writable (same choices as Google’s recurring delete dialog)</li><li><strong>Local events:</strong> Can be pushed to a writable Google calendar</li><li><strong>Conflicts:</strong> Google wins on merge</li></ul><h2 id="travel-decompress-buffers-optional" tabindex="-1">Travel / decompress buffers (optional) <a class="header-anchor" href="#travel-decompress-buffers-optional" aria-label="Permalink to &quot;Travel / decompress buffers (optional)&quot;">​</a></h2><p>In <strong>Settings → Google Calendar sync</strong>, turn on <strong>Travel / decompress buffers</strong> to add short blocks around eligible <strong>busy</strong> events:</p><ul><li><strong>Travel before</strong> — minutes before in-person meetings (or events with a location); optional travel before online meetings</li><li><strong>Decompress after</strong> — minutes after the event when meeting mode is in-person or online</li></ul><p>Buffers apply only when the parent event is <strong>busy</strong> (the default). Mark an event as free / not busy and its travel and decompress children are removed. Per-event, use <strong>Add travel / decompress buffers</strong> in the event editor to opt in or out when the global toggle is on.</p><h2 id="export-scheduled-tasks-optional" tabindex="-1">Export scheduled tasks (optional) <a class="header-anchor" href="#export-scheduled-tasks-optional" aria-label="Permalink to &quot;Export scheduled tasks (optional)&quot;">​</a></h2><p>Enable task export and choose a <strong>writable</strong> target calendar:</p><ul><li><strong>Block-based</strong> — scheduled task blocks become Google events</li><li><strong>Manual-only</strong> — export when you explicitly trigger it</li></ul><p>If no writable calendars appear, reconnect and re-approve access.</p><h2 id="scopes-and-403-errors" tabindex="-1">Scopes and 403 errors <a class="header-anchor" href="#scopes-and-403-errors" aria-label="Permalink to &quot;Scopes and 403 errors&quot;">​</a></h2><p>TemPad requests calendar scopes needed for listing calendars and reading/writing events. A <strong>403</strong> on <code>calendarList</code> usually means:</p><ul><li>Calendar API is disabled in Google Cloud, or</li><li>The access token lacks scope — use <strong>Connect calendars</strong> again after fixing the API</li></ul><p>On <strong>github.io</strong>, sign-in uses redirect instead of popup to avoid Cross-Origin-Opener-Policy issues.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><p>Google access tokens are cached in session storage. If sync stops working, reconnect calendars from Settings.</p><p>See <a href="./../troubleshooting">Troubleshooting</a> for quick fixes.</p>',24)])])}const u=o(r,[["render",t]]);export{p as __pageData,u as default};
